const raw = $('Telegram Trigger').first().json.message.text || '';

// Find email-like candidates anywhere in the text.
// Does NOT depend on commas, spaces, semicolons, or line breaks.
const candidates = raw.match(
  /[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g
) || [];

// Validate domain structure.
// Rejects things such as domains containing underscores,
// consecutive dots, labels starting/ending with "-", etc.
const isValidEmail = (email) => {
  if (email.length > 254) return false;

  const parts = email.split('@');
  if (parts.length !== 2) return false;

  const [local, domain] = parts;

  if (!local || local.length > 64) return false;
  if (local.startsWith('.') || local.endsWith('.')) return false;
  if (local.includes('..')) return false;

  const labels = domain.split('.');
  if (labels.length < 2) return false;

  for (const label of labels) {
    if (!label) return false;
    if (label.length > 63) return false;
    if (!/^[A-Za-z0-9-]+$/.test(label)) return false;
    if (label.startsWith('-') || label.endsWith('-')) return false;
  }

  return true;
};

// Validate + remove duplicates case-insensitively
const seen = new Set();

const emails = candidates.filter(email => {
  if (!isValidEmail(email)) return false;

  const key = email.toLowerCase();
  if (seen.has(key)) return false;

  seen.add(key);
  return true;
});

const cv = $('FTP').first().binary.cv;

// One item per Gmail send
return emails.map(email => ({
  json: { email },
  binary: { cv }
}));
